export const normalizePhone = (phone: string) => {
  let clean = phone.trim().replace(/\D/g, '');
  if (clean.startsWith('251')) {
    clean = '0' + clean.substring(3);
  } else if (clean.length === 9 && (clean.startsWith('9') || clean.startsWith('7'))) {
    clean = '0' + clean;
  }
  return clean;
};

