  const updateFormStatus = async (form: any, newStatus: 'approved' | 'rejected' | 'pending') => {
    setIsUpdatingForm(true);
    try {
      const updateData: any = {
        status: newStatus,
        updatedAt: serverTimestamp(),
        resolvedBy: user?.uid
      };
      
      let adminNote = await promptAction(language === 'am' ? 'ማስታወሻ (አማራጭ):' : 'Note (optional):') || '';
      if (adminNote) updateData.adminNote = adminNote;

      if (newStatus === 'approved' && form.type === 'profile_update') {
        const userRef = doc(db, 'users', form.userId);
        
        // Ensure type matching.
        const mergedBase = {
          fullName: form.newData.fullName || form.previousData.fullName || '',
          phone: form.newData.phone || form.previousData.phone || '',
          addressRegion: form.newData.addressRegion || form.previousData.addressRegion || '',
          addressZone: form.newData.addressZone || form.previousData.addressZone || '',
          addressWoreda: form.newData.addressWoreda || form.previousData.addressWoreda || '',
          addressKebele: form.newData.addressKebele || form.previousData.addressKebele || '',
          idFront: form.newData.idFront || form.previousData.idFront || '',
          idBack: form.newData.idBack || form.previousData.idBack || ''
        };

        let dbUpdates: any = {...mergedBase};
        if (form.newData.password) {
           dbUpdates.password = form.newData.password;
        }
        await updateDoc(userRef, dbUpdates);
      }

      await updateDoc(doc(db, 'admin_forms', form.id), updateData);
      
      // Notify
      await addDoc(collection(db, 'notifications'), {
        recipientId: form.userId,
        title: language === 'am' ? 'የማስተካከያ ጥያቄ' : 'Profile Update Request',
        message: newStatus === 'approved' 
           ? (language === 'am' ? 'የግል መረጃ ማስተካከያ ጥያቄዎ ጸድቋል።' : 'Your profile update request has been approved.')
           : (language === 'am' ? 'የግል መረጃ ማስተካከያ ጥያቄዎ ውድቅ ተደርጓል።' : 'Your profile update request was rejected.'),
        createdAt: new Date().toISOString(),
        read: false
      });
      triggerSuccess(language === 'am' ? 'ማሳወቂያ' : 'Notice', language === 'am' ? 'የጥያቄው ሁኔታ ተቀይሯል' : 'Request status updated');
    } catch (error: any) {
      if (error.code === 'auth/requires-recent-login') {
        triggerError(language === 'am' ? 'ዳግም መግባት ያስፈልጋል' : 'Re-authentication required', language === 'am' ? 'እባክዎ እንደገና ይግቡ።' : 'Please log out and log in again to perform this action.');
      } else {
        handleFirestoreError(error, OperationType.UPDATE, `admin_forms/${form.id}`);
      }
    } finally {
      setIsUpdatingForm(false);
    }
  };

  const approveUser = async (userId: string) => {
    try {
      await updateDoc(doc(db, 'users', userId), {
        status: 'active',
        isVerified: true,
        verifiedAt: serverTimestamp()
      });

      // Fetch user data and send SMS notification
      try {
        const userSnap = await getDoc(doc(db, 'users', userId));
        if (userSnap.exists()) {
          const uData = userSnap.data();
          if (uData.phone) {
            const amMsg = `ሰላም ${uData.fullName || 'አቢሌ'}፣ የምዝገባ ጥያቄዎ በአድሚን ተቀብሏል። አሁን ገብተው መደበኛ አገልግሎቱን መጠቀም ይችላሉ። መልካም የእቁብ ቆይታ!`;
            const enMsg = `Hello ${uData.fullName || 'Member'}, your registration request has been approved by the Admin. You can now log in and access all services. Enjoy your Equb experience!`;
            const smsMsg = language === 'am' ? amMsg : enMsg;
            await sendSMS(uData.phone, smsMsg, uData.fullName || 'Member', 'approval');
          }
        }
      } catch (smsErr) {
        console.warn("SMS sending failed, continuing anyway:", smsErr);
      }

      // Send greeting notification
      await addDoc(collection(db, 'notifications'), {
        recipientId: userId,
        title: language === 'am' ? 'እንኳን ደህና መጡ!' : 'Welcome!',
        message: language === 'am' 
          ? 'መለያዎ ጸድቋል። አሁን ሁሉንም አገልግሎቶች መጠቀም ይችላሉ።' 
          : 'Your account has been approved. You can now use all services.',
        createdAt: serverTimestamp(),
        read: false,
        type: 'approval'
      });

      triggerSuccess(language === 'am' ? 'ማሳወቂያ' : 'Notice', language === 'am' ? 'አባል በመሳካ ሁኔታ ጸድቋል' : 'User approved successfully');
    } catch (error) {
      handleFirestoreError(error, OperationType.UPDATE, `users/${userId}`);
    }
  };

  const rejectUser = async (userId: string) => {
    const reason = await promptAction(language === 'am' ? 'ለምን ውድቅ ተደረገ? (አማራጭ)' : 'Reason for rejection? (Optional)');
    if (reason === null) return; // Cancelled

    try {
      // Find the user document
      const docRef = doc(db, 'users', userId);
      const docSnap = await getDoc(docRef);
      
      if (!docSnap.exists()) {
        throw new Error('User document not found');
      }

      const userDocToReject = docSnap.data();

      // Use document ID as the ID for rejected_members
      const rejectedMemberId = userId;

      // Add to rejected_members using setDoc so we can find it by specific ID
      await setDoc(doc(db, 'rejected_members', rejectedMemberId), {
        ...userDocToReject,
        rejectionReason: reason || '',
        rejectedAt: serverTimestamp(),
        rejectedBy: user?.uid
      });

      // Send rejection notification
      await addDoc(collection(db, 'notifications'), {
        recipientId: userId,
        title: language === 'am' ? 'የምዝገባ ጥያቄዎ ውድቅ ተደርጓል' : 'Registration Rejected',
        message: language === 'am' 
          ? `መለያዎ ውድቅ ተደርጓል። ምክንያት፡ ${reason || 'ያልተገለጸ'}` 
          : `Your account registration was rejected. Reason: ${reason || 'Not specified'}`,
        createdAt: serverTimestamp(),
        read: false,
        type: 'rejection'
      });

      // Delete from users collection to allow re-registration
      await deleteDoc(doc(db, 'users', userId));

      // Remove from local state
      setAllUsers(prev => prev.filter(u => u.id !== userId));
      setPendingUsers(prev => prev.filter(u => u.id !== userId));

      // Cleanup associated data
      const collections = [
        { name: 'payments', field: 'userId' },
        { name: 'penalties', field: 'userId' },
        { name: 'notifications', field: 'recipientId' },
        { name: 'payouts', field: 'userId' },
        { name: 'support_tickets', field: 'userId' },
        { name: 'loans', field: 'userId' },
        { name: 'guarantors', field: 'userId' },
        { name: 'admin_forms', field: 'userId' },
        { name: 'messages', field: 'senderId' },
        { name: 'messages', field: 'recipientId' }
      ];

      Promise.all(collections.map(async (col) => {
        try {
          const q = query(collection(db, col.name), where(col.field, '==', userId));
          const snap = await getDocs(q);
          await Promise.all(snap.docs.map(d => deleteDoc(doc(db, col.name, d.id))));
        } catch (e) {
          console.warn(`Failed to clean up ${col.name} for user ${userId}:`, e);
        }
      }));

      triggerSuccess(language === 'am' ? 'ማሳወቂያ' : 'Notice', language === 'am' ? 'አባል ውድቅ ተደርጓል እና መረጃው ተሰርዟል' : 'User rejected and data cleared');
    } catch (error) {
      console.error("Rejection error:", error);
      handleFirestoreError(error, OperationType.UPDATE, `users/${userId}`);
    }
  };

  const toggleAdminPermission = async (adminId: string, permission: string, currentValue: boolean) => {
    try {
      // 1. Update directly client-side (logged-in Admin is fully permitted)
      const adminRef = doc(db, 'users', adminId);
      await updateDoc(adminRef, {
        [`permissions.${permission}`]: !currentValue
      });
      setAdmins(prev => prev.map(a => a.id === adminId ? { ...a, permissions: { ...a.permissions, [permission]: !currentValue } } : a));
      triggerSuccess(
        language === 'am' ? 'ተሳክቷል' : 'Success',
        language === 'am' ? 'ፈቃድ ተቀይሯል' : 'Permission updated successfully'
      );
    } catch (clientErr: any) {
      console.warn('Direct client-side permission update failed, trying backend fallback:', clientErr);
      try {
        const response = await fetch('/api/admin/toggle-permission', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ 
            adminUid: adminId, 
            permission, 
            value: !currentValue, 
            requesterUid: auth.currentUser?.uid 
          })
        });
        if (!response.ok) throw new Error('Backend failed');
        setAdmins(prev => prev.map(a => a.id === adminId ? { ...a, permissions: { ...a.permissions, [permission]: !currentValue } } : a));
        triggerSuccess(
          language === 'am' ? 'ተሳክቷል' : 'Success',
          language === 'am' ? 'ፈቃድ ተቀይሯል' : 'Permission updated successfully'
        );
      } catch (backendErr) {
        triggerSuccess(language === 'am' ? 'ማሳወቂያ' : 'Notice', language === 'am' ? 'ፈቃድ መቀየር አልተቻለም' : 'Failed to update permission');
      }
    }
  };

  const hardDeleteAdmin = async (adminId: string) => {
    try {
      const adminToDel = admins.find(a => a.id === adminId) || allUsers.find(u => u.id === adminId);
      
      // 1. Delete Firestore user document from client (logged-in Admin is fully permitted)
      await deleteDoc(doc(db, 'users', adminId));
      
      // Decrement member count from group if user belongs to one
      if (adminToDel?.groupId) {
        try {
          const groupRef = doc(db, 'groups', adminToDel.groupId);
          const groupSnap = await getDoc(groupRef);
          if (groupSnap.exists()) {
            const currentCount = groupSnap.data().memberCount || 0;
            const slots = adminToDel.slots || 1;
            const newCount = Math.max(0, currentCount - slots);
            await updateDoc(groupRef, {
              memberCount: newCount,
              status: 'open'
            });
          }
        } catch (groupError) {
          console.error("Error reverting group member count", groupError);
        }
      }

      // 2. Try to clean up from Firebase Auth on backend
      try {
        const response = await fetch('/api/admin/delete-admin', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ 
            adminUid: adminId, 
            requesterUid: auth.currentUser?.uid 
          })
        });

        if (!response.ok) {
          const errorData = await response.json().catch(() => ({}));
          console.warn('Backend Auth account deletion warning:', errorData.error || 'Server error');
        }
      } catch (backendErr) {
        console.warn('Backend Auth account deletion failed:', backendErr);
      }

      setAdmins(prev => prev.filter(a => a.id !== adminId));
      setAllUsers(prev => prev.filter(u => u.id !== adminId));

      // Cleanup associated data
      const collections = [
        { name: 'payments', field: 'userId' },
        { name: 'penalties', field: 'userId' },
        { name: 'notifications', field: 'recipientId' },
        { name: 'payouts', field: 'userId' },
        { name: 'support_tickets', field: 'userId' },
        { name: 'loans', field: 'userId' },
        { name: 'guarantors', field: 'userId' },
        { name: 'admin_forms', field: 'userId' },
        { name: 'messages', field: 'senderId' },
        { name: 'messages', field: 'recipientId' }
      ];

      Promise.all(collections.map(async (col) => {
        try {
          const q = query(collection(db, col.name), where(col.field, '==', adminId));
          const snap = await getDocs(q);
          await Promise.all(snap.docs.map(d => deleteDoc(doc(db, col.name, d.id))));
        } catch (e) {
          console.warn(`Failed to clean up ${col.name} for admin ${adminId}:`, e);
        }
      }));

      triggerSuccess(language === 'am' ? 'ተሳክቷል' : 'Success', language === 'am' ? 'አድሚኑ ከሲስተሙ ሙሉ በሙሉ ተወግዷል' : 'Admin permanently removed from system');
    } catch (error: any) {
      console.error('Error hard deleting admin:', error);
      triggerSuccess(language === 'am' ? 'ማሳወቂያ' : 'Notice', language === 'am' ? `ስህተት ተከስቷል: ${error.message}` : `Error: ${error.message}`);
    }
  };

  const deleteUserAdmin = (userId: string) => {
    if (!isSuperAdmin) {
      triggerSuccess(language === 'am' ? 'የመሰረዝ ስልጣን' : 'Unauthorized', language === 'am' ? 'አባላትን መደለት የሚችለው ዋና አድሚን ብቻ ነው። እባክዎ ለዋና አድሚን ያሳውቁ።' : 'Only the Super Admin can delete members/admins. Please contact the Super Admin.');
      return;
    }
    if (userId === auth.currentUser?.uid) {
      triggerSuccess(language === 'am' ? 'ስህተት' : 'Error', language === 'am' ? 'ራስዎን መሰረዝ አይችሉም' : 'You cannot delete yourself');
      return;
    }
    setUserToDelete({ id: userId });
  };

  const confirmDeleteUserAdmin = async () => {
    if (!userToDelete) return;
    const userId = userToDelete.id;
    
    const userToDel = allUsers.find(u => u.id === userId) || admins.find(a => a.id === userId);
    
    setUserToDelete(null);

    // Optimistic update
    setAllUsers(prev => prev.filter(u => u.id !== userId));
    setAdmins(prev => prev.filter(a => a.id !== userId));
    
    try {
      await deleteDoc(doc(db, 'users', userId));
      
      // Decrement member count from group if user belongs to one
      if (userToDel?.groupId) {
        try {
          const groupRef = doc(db, 'groups', userToDel.groupId);
          const groupSnap = await getDoc(groupRef);
          if (groupSnap.exists()) {
            const currentCount = groupSnap.data().memberCount || 0;
            const slots = userToDel.slots || 1;
            const newCount = Math.max(0, currentCount - slots);
            await updateDoc(groupRef, {
              memberCount: newCount,
              status: 'open' // Group is explicitly open again when members are deleted
            });
          }
        } catch (groupError) {
          console.error("Error reverting group member count", groupError);
        }
      }
      
      // Delete from Firebase Auth
      try {
        await fetch('/api/admin/delete-admin', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ adminUid: userId, requesterUid: auth.currentUser?.uid })
        });
      } catch (e) {
        console.error("Failed to delete user from Auth backend", e);
      }

      triggerSuccess(language === 'am' ? 'ተሳክቷል' : 'Success', language === 'am' ? 'ተጠቃሚው/አድሚኑ በተሳካ ሁኔታ ተሰርዟል' : 'Deleted successfully');
      
      // 2. Clear rejected members if exists
      try {
        await deleteDoc(doc(db, 'rejected_members', userId));
      } catch (e) {}

      // 3. Clean up associated data in the background (no need to await if we want it to be fast)
      const deleteCollectionDocs = async (collectionName: string, field: string) => {
        try {
          const q = query(collection(db, collectionName), where(field, '==', userId));
          const snap = await getDocs(q);
          const deletions = snap.docs.map(d => deleteDoc(doc(db, collectionName, d.id)));
          await Promise.all(deletions);
        } catch (e) {
          console.warn(`Failed to clean up ${collectionName}:`, e);
        }
      };

      // Run cleanup in background without blocking
      Promise.all([
        deleteCollectionDocs('payments', 'userId'),
        deleteCollectionDocs('penalties', 'userId'),
        deleteCollectionDocs('notifications', 'recipientId'),
        deleteCollectionDocs('payouts', 'userId'),
        deleteCollectionDocs('support_tickets', 'userId'),
        deleteCollectionDocs('loans', 'userId'),
        deleteCollectionDocs('guarantors', 'userId'),
        deleteCollectionDocs('admin_forms', 'userId'),
        deleteCollectionDocs('messages', 'senderId'),
        deleteCollectionDocs('messages', 'recipientId')
      ]);

    } catch (error) {
      handleFirestoreError(error, OperationType.DELETE, `users/${userId}`);
    }
  };

